const SAFE_IAT_FALLBACK = Math.floor(Date.parse('2020-01-01T00:00:00Z') / 1000);

(async () => {
const baseUrl = global.get('getBaseUrl')(msg);

// Disk-backed (see boot tab) so revocations made via /admin persist across
// pod restarts, unlike Node-RED's default in-memory global context.
const bits = global.get('loadStatusBits')();

let issuerKeyPem, issuerCertDerB64, rootCaCertDerB64;
const pki = global.get('pki');
if (pki) {
    issuerKeyPem = pki.issuerKeyPem;
    issuerCertDerB64 = pki.issuerCertDerB64;
    rootCaCertDerB64 = pki.rootCaCertDerB64;
} else {
    issuerKeyPem = fs.readFileSync('/data/pki/issuer.key', 'utf8');
    const issuerCertPem = fs.readFileSync('/data/pki/issuer.crt', 'utf8');
    const rootCaCertPem = fs.readFileSync('/data/pki/root-ca.crt', 'utf8');
    issuerCertDerB64 = new crypto.X509Certificate(issuerCertPem).raw.toString('base64');
    rootCaCertDerB64 = new crypto.X509Certificate(rootCaCertPem).raw.toString('base64');
}

const compressed = zlib.deflateSync(bits).toString('base64url');

// See the boot tab's getRealWorldNowSeconds comment: this container's own
// clock can't be trusted, so fetch real time from an external HTTPS Date
// header, falling back to a safely-past fixed anchor if that fails.
const realNow = await global.get('getRealWorldNowSeconds')();
const iat = realNow || SAFE_IAT_FALLBACK;

const header = { alg: 'ES256', typ: 'statuslist+jwt', x5c: [issuerCertDerB64, rootCaCertDerB64] };
const payload = {
    iss: baseUrl,
    sub: baseUrl + '/status-list/1',
    iat,
    status_list: { bits: 1, lst: compressed }
};

const b64url = (obj) => Buffer.from(JSON.stringify(obj)).toString('base64url');
const signingInput = b64url(header) + '.' + b64url(payload);
const signature = crypto.sign('sha256', Buffer.from(signingInput), {
    key: crypto.createPrivateKey(issuerKeyPem),
    dsaEncoding: 'ieee-p1363'
});
const jwt = signingInput + '.' + signature.toString('base64url');

msg.headers = { 'content-type': 'application/statuslist+jwt' };
msg.payload = jwt;
node.send(msg);
})();
return null;
